import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

public class Educational {
    public static void main(String[] args) throws IOException {
        Educational c = new Educational();
        c.start();
    }

    private void start() throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer str = new StringTokenizer(in.readLine());
        int n = Integer.parseInt(str.nextToken());
        String s = in.readLine();
        int[] b = new int[n];

        str = new StringTokenizer(in.readLine());
        for (int i = 0; i < n; ++i) {
            b[i] = Integer.parseInt(str.nextToken());
        }

        // Count frequency of each character
        int[] freq = new int[26];
        for (char c : s.toCharArray()) {
            freq[c - 'a']++;
        }

        // Check if it's possible to form an antipalindromic string
        for (int i = 0; i < 26; i++) {
            if (freq[i] % 2 != 0) {
                System.out.println(0);
                return;
            }
        }

        // Create pairs for antipalindromic requirement
        // For each position i in first half, we need to pair with position n-1-i in second half
        // such that characters at these positions are different

        // Build a graph where we need to assign characters to positions
        // Each position in first half must be paired with a different character in second half

        // Use maximum weight matching approach
        // For each pair of positions (i, n-1-i), we want to assign two different characters

        // Create list of pairs
        List<int[]> pairs = new ArrayList<>();
        for (int i = 0; i < n / 2; i++) {
            pairs.add(new int[]{i, n - 1 - i});
        }

        // Try all possible assignments using backtracking with pruning
        char[] res = s.toCharArray();
        int[] bestBeauty = new int[]{0};

        // Sort positions by beauty in descending order for better pruning
        Integer[] indices = new Integer[n / 2];
        for (int i = 0; i < n / 2; i++) indices[i] = i;
        Arrays.sort(indices, (a, b) -> Integer.compare(b[0] + b[1], a[0] + a[1]));

        backtrack(res, b, pairs, 0, new int[n], bestBeauty);

        System.out.println(bestBeauty[0]);
    }

    private void backtrack(char[] s, int[] b, List<int[]> pairs, int idx, int[] assigned, int[] bestBeauty) {
        if (idx == pairs.size()) {
            int sum = 0;
            for (int i = 0; i < s.length; i++) {
                if (s[i] == assigned[i] + 'a') {
                    sum += b[i];
                }
            }
            bestBeauty[0] = Math.max(bestBeauty[0], sum);
            return;
        }

        int[] pair = pairs.get(idx);
        int i = pair[0];
        int j = pair[1];

        // Try all possible character pairs for positions i and j
        for (int ci = 0; ci < 26; ci++) {
            for (int cj = 0; cj < 26; cj++) {
                if (ci == cj) continue; // Must be different for antipalindromic

                // Check if we have enough characters available
                int[] freq = new int[26];
                for (int k = 0; k < s.length; k++) {
                    if (assigned[k] == -1) {
                        freq[s[k] - 'a']++;
                    }
                }

                // Temporarily assign
                if (freq[ci] > 0 && freq[cj] > 0) {
                    freq[ci]--;
                    freq[cj]--;

                    // Check if remaining characters can form valid pairs
                    boolean valid = true;
                    for (int k = 0; k < 26; k++) {
                        if (freq[k] % 2 != 0) {
                            valid = false;
                            break;
                        }
                    }

                    if (valid) {
                        int oldI = assigned[i];
                        int oldJ = assigned[j];
                        assigned[i] = ci;
                        assigned[j] = cj;

                        backtrack(s, b, pairs, idx + 1, assigned, bestBeauty);

                        assigned[i] = oldI;
                        assigned[j] = oldJ;
                    }
                }
            }
        }
    }
}
